target.css:
:root {
  --ink: #19342f;
  --deep: #12302b;
  --moss: #2c5950;
  --mint: #a8d7bb;
  --paper: #f6f0df;
  --sand: #e4d3a8;
  --lime: #c7e85b;
  --amber: #f4bd52;
  --coral: #e97961;
}

.retrieval {
  width: 500px;
  box-sizing: border-box;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.retrieval-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 14px;
  color: var(--paper);
  background: var(--deep);
}

.heading p,
.heading h1,
.camera figcaption,
.section-kicker,
.coordinates,
.route-note,
.retrieval-footer p {
  margin: 0;
}

.heading p {
  color: var(--mint);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
}

.heading h1 {
  margin-top: 2px;
  font-size: 20px;
  line-height: 1.05;
  letter-spacing: -.03em;
}

.status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  color: var(--deep);
  background: var(--lime);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.status i {
  width: 7px;
  height: 7px;
  background: var(--deep);
  border-radius: 50%;
}

.console {
  display: grid;
  grid-template-columns: 124px 1fr 130px;
  gap: 10px;
  padding: 12px;
}

.camera,
.telemetry,
.route {
  box-sizing: border-box;
  min-height: 128px;
  border: 1px solid var(--ink);
}

.camera {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin: 0;
  background: var(--sand);
  border-radius: 12px 4px 12px 4px;
}

.camera-label,
.section-kicker {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.camera-icon {
  position: relative;
  width: 45px;
  height: 31px;
  background: var(--moss);
  border: 2px solid var(--ink);
  border-radius: 7px;
}

.camera-icon::before {
  position: absolute;
  top: -8px;
  left: 7px;
  width: 15px;
  height: 7px;
  content: "";
  background: var(--moss);
  border: 2px solid var(--ink);
  border-bottom: 0;
  border-radius: 4px 4px 0 0;
}

.camera-icon b {
  position: absolute;
  top: 7px;
  left: 14px;
  width: 13px;
  height: 13px;
  background: var(--lime);
  border: 2px solid var(--ink);
  border-radius: 50%;
}

.camera figcaption {
  font-size: 11px;
  line-height: 1.35;
  text-align: center;
}

.telemetry {
  padding: 11px;
  background: var(--mint);
  border-radius: 4px 12px 4px 12px;
}

.readings {
  display: grid;
  gap: 5px;
  padding: 7px 0 0;
  margin: 0;
  list-style: none;
}

.readings li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--moss);
  font-size: 12px;
}

.readings span {
  color: var(--moss);
}

.readings strong {
  font-size: 12px;
}

.route {
  padding: 10px;
  background: var(--paper);
  border-radius: 12px 4px 12px 4px;
}

.route-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}

.route-top h2 {
  margin: 0;
  font-size: 13px;
  line-height: 1;
}

.route-top span {
  padding: 3px 5px;
  color: var(--deep);
  background: var(--amber);
  border-radius: 4px;
  font-size: 10px;
  font-weight: 800;
}

.coordinates {
  margin-top: 7px;
  color: var(--moss);
  font-size: 10px;
  line-height: 1.25;
}

.track {
  display: flex;
  align-items: center;
  gap: 3px;
  margin: 10px 0 8px;
}

.track span {
  width: 19px;
  height: 7px;
  background: var(--lime);
  border: 1px solid var(--ink);
  border-radius: 99px;
}

.track span:nth-child(3) {
  background: var(--amber);
}

.track span:nth-child(4) {
  background: var(--coral);
}

.route-note {
  font-size: 10px;
  font-weight: 700;
  line-height: 1.25;
}

.retrieval-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 14px;
  background: var(--sand);
  border-top: 2px solid var(--ink);
}

.retrieval-footer p {
  font-size: 12px;
}

.retrieval-footer button {
  padding: 7px 9px;
  color: var(--paper);
  background: var(--moss);
  border: 1px solid var(--ink);
  border-radius: 7px;
  font-size: 11px;
  font-weight: 800;
}

.retrieval-footer button span {
  margin-left: 5px;
  color: var(--lime);
  font-size: 14px;
}

